world node {
    use aap:caps/types@0.1.0.{tick, run-info};

    import wasi:clocks/wall-clock@0.2.0;

    export run: func(tick: tick) -> run-info;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let secs = now.seconds;
        RunInfo {
            date: format_date(secs),
            started: secs,
        }
    }
}

/// Formats the UTC calendar date of `secs` (seconds since the Unix epoch) as
/// `YYYY-MM-DD`. The year is clamped to 0..=9999 so the result is always
/// exactly ten characters.
fn format_date(secs: u64) -> String {
    let days = (secs / 86_400) as i64;
    let (y, m, d) = civil_from_days(days);
    let y = y.clamp(0, 9999);
    format!("{:04}-{:02}-{:02}", y, m, d)
}

/// Converts days since 1970-01-01 to (year, month, day) in the proleptic
/// Gregorian calendar. Adapted from Howard Hinnant's `civil_from_days`.
fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    let y = if m <= 2 { y + 1 } else { y };
    (y, m, d)
}

export!(Node);
